def nested_type_counter(nested):
    counts = {}
    def recurse(item):
        if isinstance(item, bool):
            counts['bool'] = counts.get('bool', 0) + 1
        elif isinstance(item, int):
            counts['int'] = counts.get('int', 0) + 1
        elif isinstance(item, float):
