        elif isinstance(item, list):
            counts['list'] = counts.get('list', 0) + 1
            for elem in item:
                recurse(elem)
        elif isinstance(item, tuple):
            counts['tuple'] = counts.get('tuple', 0) + 1
            for elem in item:
