try:
    with open('data.txt', 'r') as f:
        nums = [line.strip() for line in f if line.strip()]
    if not nums:
        print('Empty file')
    else:
        evens = []
        odds = []
        for n in nums:
            try:
                val = int(n)
                if val % 2 == 0:
                    evens.append(str(val))
                else:
                    odds.append(str(val))
            except ValueError:
                continue
        with open('even.txt', 'w') as f:
            f.write('\n'.join(evens) + ('\n' if evens else ''))
        with open('odd.txt', 'w') as f:
            f.write('\n'.join(odds) + ('\n' if odds else ''))
except FileNotFoundError:
    print('File not found')

